const X = s => String(s).replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F]/g,'').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
const CI = {red:'C8102E', crimson:'8B0000', gold:'F4CD00', green:'006838', navy:'1D2D5F', parch:'FDF8EE', ink:'2C2C2C', gray:'9E9E9E', pearl:'E8E8E8'};
function runs(text, o={}){
  const parts = String(text).split(/([฀-๿]+(?:[  ]+[฀-๿]+)*)/).filter(s=>s!=='');
  return parts.map(p=>{
    const th=/[฀-๿]/.test(p);
    const rpr='<w:rPr>'+(o.b?'<w:b/><w:bCs/>':'')+(o.i?'<w:i/><w:iCs/>':'')+(o.color?'<w:color w:val="'+o.color+'"/>':'')+(o.sz?'<w:sz w:val="'+o.sz+'"/><w:szCs w:val="'+o.sz+'"/>':'')+(th?'<w:lang w:val="th-TH" w:eastAsia="th-TH" w:bidi="th-TH"/>':'<w:lang w:val="en-US" w:bidi="th-TH"/>')+'</w:rPr>';
    return '<w:r>'+rpr+'<w:t xml:space="preserve">'+X(p)+'</w:t></w:r>';
  }).join('');
}
function para(inner, o={}){
  let ppr='';
  if(o.style) ppr+='<w:pStyle w:val="'+o.style+'"/>';
  if(o.keep) ppr+='<w:keepNext/>';
  if(o.shade) ppr+='<w:pBdr><w:left w:val="single" w:sz="24" w:space="8" w:color="'+CI.red+'"/></w:pBdr><w:shd w:val="clear" w:color="auto" w:fill="'+o.shade+'"/>';
  ppr+='<w:spacing w:before="'+(o.before||0)+'" w:after="'+(o.after==null?100:o.after)+'"/>';
  if(o.ind) ppr+='<w:ind w:left="'+o.ind+'"/>';
  if(o.jc) ppr+='<w:jc w:val="'+o.jc+'"/>';
  return '<w:p><w:pPr>'+ppr+'</w:pPr>'+inner+'</w:p>';
}
const P = (t,o={},r={}) => para(runs(t,r),o);
const H1 = t => para(runs(t),{style:'Heading1',keep:true});
const H2 = t => para(runs(t),{style:'Heading2',keep:true});
const EMPTY = () => P('(กลุ่มยังไม่ได้กรอกส่วนนี้)',{},{i:true,color:CI.gray});
function cellXml(text,w,o={}){
  return '<w:tc><w:tcPr><w:tcW w:w="'+w+'" w:type="dxa"/>'+(o.span?'<w:gridSpan w:val="'+o.span+'"/>':'')+(o.fill?'<w:shd w:val="clear" w:color="auto" w:fill="'+o.fill+'"/>':'')+'<w:tcMar><w:top w:w="60" w:type="dxa"/><w:bottom w:w="60" w:type="dxa"/></w:tcMar></w:tcPr>'+
    String(text||'').split('\n').map(l=>P(l,{after:0},{b:o.b,color:o.color,sz:o.sz||26})).join('')+'</w:tc>';
}
function table(rows, widths, o={}){
  const total=widths.reduce((a,b)=>a+b,0);
  const bd = '<w:tblBorders>'+['top','left','bottom','right','insideH','insideV'].map(s=>'<w:'+s+' w:val="single" w:sz="4" w:space="0" w:color="'+(o.border||'BDBDBD')+'"/>').join('')+'</w:tblBorders>';
  let x='<w:tbl><w:tblPr><w:tblW w:w="'+total+'" w:type="dxa"/>'+bd+'<w:tblLayout w:type="fixed"/><w:tblCellMar><w:left w:w="100" w:type="dxa"/><w:right w:w="100" w:type="dxa"/></w:tblCellMar></w:tblPr><w:tblGrid>'+widths.map(w=>'<w:gridCol w:w="'+w+'"/>').join('')+'</w:tblGrid>';
  rows.forEach((r,i)=>{
    const head = o.header && i===0;
    x+='<w:tr>'+(head?'<w:trPr><w:tblHeader/></w:trPr>':'');
    let k=0;
    r.forEach(c=>{
      const cell = typeof c==='object'&&c!==null?c:{t:c};
      const span=cell.span||1; const w=widths.slice(k,k+span).reduce((a,b)=>a+b,0); k+=span;
      x+=cellXml(cell.t,w,head?{fill:CI.red,color:'FFFFFF',b:true}:{fill:cell.fill,b:cell.b,span:span>1?span:0,color:cell.color});
    });
    x+='</w:tr>';
  });
  return x+'</w:tbl>'+P('',{after:60});
}
// pasted text -> paragraphs and tables (markdown pipes or tab-separated)
function cleanMd(l){return l.replace(/^#{1,6}\s+/,'').replace(/\*\*(.+?)\*\*/g,'$1').replace(/__(.+?)__/g,'$1').replace(/^\s*[-*•]\s+/,'• ').replace(/`/g,'');}
function blocks(text){
  const lines=String(text||'').replace(/\r/g,'').split('\n'); const out=[]; let tb=null;
  const isRow = l => (l.split('|').length>=3 && l.trim().length>0) || l.includes('\t');
  const cells = l => l.includes('\t') && !l.includes('|') ? l.split('\t').map(s=>s.trim()) : l.trim().replace(/^\|/,'').replace(/\|$/,'').split('|').map(s=>s.trim());
  const flush=()=>{ if(tb){ out.push({tbl:tb}); tb=null; } };
  lines.forEach(l=>{
    if(isRow(l)){ if(/^[\s|:\-]+$/.test(l)) return; (tb=tb||[]).push(cells(l).map(cleanMd)); }
    else { flush(); if(l.trim()) out.push({p:cleanMd(l)}); }
  });
  flush(); return out;
}
const FULLW = 9638;
function body(text){
  if(!String(text||'').trim()) return EMPTY();
  return blocks(text).map(b=>{
    if(b.p) return P(b.p,{after:80});
    const n=Math.max(...b.tbl.map(r=>r.length));
    const rows=b.tbl.map(r=>{const rr=r.slice(); while(rr.length<n) rr.push(''); return rr;});
    const w=Array(n).fill(Math.floor(FULLW/n));
    return table(rows,w,{header:rows.length>1});
  }).join('');
}
const val = id => { const el=document.getElementById(id); return el?el.value.trim():''; };

const LOGO_B64 = '';

function stylesXml(){
  const rf='<w:rFonts w:ascii="Sarabun" w:hAnsi="Sarabun" w:eastAsia="Sarabun" w:cs="Sarabun"/>';
  const h=(id,name,sz,color,extra)=>'<w:style w:type="paragraph" w:styleId="'+id+'"><w:name w:val="'+name+'"/><w:basedOn w:val="Normal"/><w:next w:val="Normal"/><w:qFormat/><w:pPr><w:keepNext/>'+extra+'<w:outlineLvl w:val="'+(id==='Heading1'?0:1)+'"/></w:pPr><w:rPr><w:b/><w:bCs/><w:color w:val="'+color+'"/><w:sz w:val="'+sz+'"/><w:szCs w:val="'+sz+'"/></w:rPr></w:style>';
  return '<?xml version="1.0" encoding="UTF-8" standalone="yes"?><w:styles xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main"><w:docDefaults><w:rPrDefault><w:rPr>'+rf+'<w:color w:val="'+CI.ink+'"/><w:sz w:val="30"/><w:szCs w:val="30"/><w:lang w:val="th-TH" w:eastAsia="en-US" w:bidi="th-TH"/></w:rPr></w:rPrDefault><w:pPrDefault><w:pPr><w:spacing w:after="100" w:line="264" w:lineRule="auto"/></w:pPr></w:pPrDefault></w:docDefaults>'+
   '<w:style w:type="paragraph" w:default="1" w:styleId="Normal"><w:name w:val="Normal"/><w:qFormat/></w:style>'+
   h('Heading1','heading 1',36,CI.red,'<w:pBdr><w:bottom w:val="single" w:sz="8" w:space="2" w:color="'+CI.gold+'"/></w:pBdr><w:spacing w:before="320" w:after="120"/>')+
   h('Heading2','heading 2',30,CI.navy,'<w:spacing w:before="160" w:after="60"/>')+
   '<w:style w:type="paragraph" w:styleId="Footer"><w:name w:val="footer"/><w:basedOn w:val="Normal"/><w:rPr><w:color w:val="'+CI.gray+'"/><w:sz w:val="20"/><w:szCs w:val="20"/></w:rPr></w:style></w:styles>';
}
function footerXml(){
  const fld = '<w:r><w:fldChar w:fldCharType="begin"/></w:r><w:r><w:instrText xml:space="preserve"> PAGE </w:instrText></w:r><w:r><w:fldChar w:fldCharType="separate"/></w:r><w:r><w:t>1</w:t></w:r><w:r><w:fldChar w:fldCharType="end"/></w:r>';
  return '<?xml version="1.0" encoding="UTF-8" standalone="yes"?><w:ftr xmlns:w="http://schemas.openxmlformats.org/wordprocessingml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><w:p><w:pPr><w:pStyle w:val="Footer"/><w:pBdr><w:top w:val="single" w:sz="12" w:space="4" w:color="'+CI.red+'"/></w:pBdr><w:jc w:val="center"/></w:pPr>'+runs('คณะเภสัชศาสตร์ มหาวิทยาลัยธรรมศาสตร์  |  pharm.tu.ac.th  |  AI for Health Students · Workflow Lab  |  หน้า ')+fld+'</w:p></w:ftr>';
}
async function buildDocx(WID){
  const zip = new JSZip();
  zip.file('[Content_Types].xml','<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Default Extension="png" ContentType="image/png"/><Override PartName="/word/document.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.document.main+xml"/><Override PartName="/word/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.styles+xml"/><Override PartName="/word/footer1.xml" ContentType="application/vnd.openxmlformats-officedocument.wordprocessingml.footer+xml"/><Override PartName="/docProps/core.xml" ContentType="application/vnd.openxmlformats-package.core-properties+xml"/></Types>');
  zip.file('_rels/.rels','<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="word/document.xml"/><Relationship Id="rId2" Type="http://schemas.openxmlformats.org/package/2006/relationships/metadata/core-properties" Target="docProps/core.xml"/></Relationships>');
  zip.file('docProps/core.xml','<?xml version="1.0" encoding="UTF-8" standalone="yes"?><cp:coreProperties xmlns:cp="http://schemas.openxmlformats.org/package/2006/metadata/core-properties" xmlns:dc="http://purl.org/dc/elements/1.1/" xmlns:dcterms="http://purl.org/dc/terms/" xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance"><dc:title>Workflow Lab สรุปของกลุ่ม</dc:title><dc:creator>'+X(val('grp')||'กลุ่ม')+'</dc:creator><dcterms:created xsi:type="dcterms:W3CDTF">'+new Date().toISOString().slice(0,19)+'Z</dcterms:created></cp:coreProperties>');
  zip.file('word/_rels/document.xml.rels','<?xml version="1.0" encoding="UTF-8" standalone="yes"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rIdS" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/><Relationship Id="rIdF" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/footer" Target="footer1.xml"/><Relationship Id="rIdL" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/image" Target="media/logo.png"/></Relationships>');
  zip.file('word/styles.xml',stylesXml());
  zip.file('word/footer1.xml',footerXml());
  zip.file('word/media/logo.png',LOGO_B64,{base64:true});
  zip.file('word/document.xml',documentXml('rIdL',WID));
  return zip.generateAsync({type:'blob',mimeType:'application/vnd.openxmlformats-officedocument.wordprocessingml.document'});
}




const today = ()=>{ try{ return new Date().toLocaleDateString('th-TH',{year:'numeric',month:'long',day:'numeric'}); }catch(e){ return new Date().toISOString().slice(0,10); } };
function monoXml(txt){ return String(txt).split('\n').map(l=>P(l||' ',{shade:'EEF1F6',after:0,ind:120},{sz:22})).join('')+P('',{after:80}); }
function wfData(id){const w=WF.find(x=>x.id===id),g=G();return{w,g,grp:val('grp')||'(ยังไม่ได้ระบุกลุ่ม)',mem:val('mem')||'(ยังไม่ได้ระบุ)',
 steps:w.steps.map((s,i)=>({s,i,st:+store.get(K(id,i)+'-s',0),note:(store.get(K(id,i),'')||'').trim(),hz:s.h.map((x,k)=>x==='-'?'':HN[k]+': '+x).filter(Boolean).join('  ·  ')})),find:(store.get(K(id,'f'),'')||'').trim()}}
