  const lw=[2600,FULLW-2600], F_=t=>({t,b:true,fill:CI.parch});
  let x=band+table([[F_('กลุ่ม'),d.grp],[F_('สมาชิก'),d.mem],[F_('วันที่'),today()],[F_('ผู้เรียน'),d.g.role],[F_('หัวข้อที่ใช้ฝึก'),d.g.topic],[F_('สถานการณ์'),d.w.sc]],lw,{border:CI.pearl});
  x+=P('AI Harness: Model × Prompt × Context × Tools × Human ตัวใดเป็นศูนย์ ผลลัพธ์ก็เป็นศูนย์ เคสและข้อมูลผู้ป่วยในเอกสารนี้เป็นข้อมูลสมมติเพื่อการเรียน',{shade:CI.parch,after:160,before:60,jc:'thaiDistribute'});
  x+=H1('ภาพรวมของ workflow')+table([['ขั้น','ใครทำ','ผลลัพธ์','บันทึกของกลุ่ม']].concat(d.steps.map(o=>[(o.i+1)+'. '+o.s.t,WHO[o.s.w][1],o.s.w==='hu'?'-':starTxt(o.st),o.note||'-'])),[3300,1300,1700,FULLW-6300],{header:true});
  x+=H1('รายละเอียดแต่ละขั้น');
  d.steps.forEach(o=>{x+=H2('ขั้นที่ '+(o.i+1)+' · '+o.s.t+' ('+WHO[o.s.w][1]+')')+P(o.s.hint,{after:60},{color:CI.gray,sz:26});
    if(o.hz)x+=P('Harness  '+(o.s.p?'Prompt: R-T-F-C  ·  ':'')+o.hz,{after:80},{sz:24,color:CI.navy});
    if(o.s.p)x+=monoXml(fill(o.s.p));
    if(o.s.w!=='hu')x+=P('ผลลัพธ์: '+starTxt(o.st),{after:40},{b:true});
    x+=o.note?P('บันทึกของกลุ่ม: '+o.note):EMPTY();});
  x+=H1('สิ่งที่กลุ่มเราค้นพบ')+(d.find?body(d.find):EMPTY());
